#[derive(Default)]
pub struct StaticHistoryInvokeParams {
    pub resumed: Option<u8>,
}

// ======================================================================
// Policy struct
// ======================================================================

pub struct StaticHistoryPolicy {
    /// W3C SCXML 5.2: the `resumed` datamodel variable, published (`sce:direction="out"`).
    resumed: u8,
    // W3C SCXML 5.10: the session's id (script engine, invoke tracking, the
    // saved state), bound when the machine is built and never empty
    // (docs/adr/0045): drawn, given by the host, or given by the parent.
    pub session_id: Option<String>,
    // W3C SCXML 6.4: Parent engine external queue for #_parent send routing
    // Always generated under std — any SM can be invoked as a child. Under
    // `--no-std` (SCE Protocol-Synthesis RFC §synth-5-J-2) the SCXML `<invoke>` element
    // is codegen-rejected, so no parent_external_queue handle is ever
    // wired in, and the Arc<Mutex<...>> (alloc-coupled) is omitted.
    pub parent_external_queue: Option<std::sync::Arc<std::sync::Mutex<Vec<(String, String)>>>>,
    // W3C SCXML 6.4.1: This child's invoke ID (for _event.invokeid in parent).
    // SCE Protocol-Synthesis RFC §synth-5-J-2: gated to !no_std — `<invoke>` is codegen-rejected
    // under no_std, so a machine is never instantiated as a child and this
    // identity is dead. Mirrors the `parent_external_queue` / `invoke` module gate.
    pub invoke_id: String,
    // W3C SCXML 6.5: Child session ID for finalize origin matching.
    pub child_session_id: String,
}

impl StaticHistoryPolicy {
    fn build(session_id: String) -> Self {
        let resumed: u8 = 0;
        Self {
            resumed,
            session_id: Some(session_id),
            parent_external_queue: None,
            invoke_id: String::new(),
            child_session_id: String::new(),
        }
    }

    /// Build the machine under a session id drawn from the operating system's
    /// randomness, a UUID version 4 (docs/adr/0045).    ///
    /// Absent on a target with no source of randomness the runtime reads
    /// (`wasm32-unknown-unknown`): a host there gives the id, through
    /// [`new_with_session_id`](Self::new_with_session_id).
    #[cfg(not(any(target_os = "none", all(target_arch = "wasm32", target_os = "unknown"))))]
    pub fn new() -> Self {
        Self::build(::sce_rust_runtime::helpers::session_id::drawn())
    }

    /// Build the machine under the session id its host gives: the host's own
    /// name for the machine, say, or a fixed id a test holds a saved text to
    /// (docs/adr/0045, "Questions the owner answered" 2). `_sessionid` is bound
    /// here and kept until the session ends; a restore binds the saved id in
    /// its place, since the session carries on.    ///
    /// The one way this machine is built on `wasm32-unknown-unknown`, which has
    /// no source of randomness the runtime reads.
    ///
    /// # Errors
    ///
    /// An id that is not an XML Nmtoken (the empty text, a space, a `#`) is
    /// refused with the reason, and no machine is built.
    pub fn new_with_session_id(
        session_id: &str,
    ) -> Result<Self, ::sce_rust_runtime::helpers::session_id::SessionIdRefusal> {
        Ok(Self::build(::sce_rust_runtime::helpers::session_id::given(
            session_id,
        )?))
    }

    /// The policy of a child its parent invokes, under the id the tree gives it,
    /// `<parent>.<invokeid>` (docs/adr/0045): formed by the parent from its own
    /// id and the invoke id, both held to the rule already, so it is not
    /// judged again.
    pub(crate) fn for_child(session_id: String) -> Self {
        Self::build(session_id)
    }

    /// §scxml-6.4.1: give this machine the values `params` carries, in place of
    /// the ones its `<data>` gave. Called before it initializes.
    pub fn accept_params(&mut self, params: StaticHistoryInvokeParams) {
        if let Some(value) = params.resumed {
            self.resumed = value;
        }
    }

    /// W3C SCXML 5.2: what the published `resumed` datamodel variable
    /// holds now. Only the machine writes it.
    pub fn resumed(&self) -> u8 {
        self.resumed
    }
}

// docs/adr/0045: a machine built with no arguments draws its session id, so it
// has a default only where `new` can draw one.
#[cfg(not(any(target_os = "none", all(target_arch = "wasm32", target_os = "unknown"))))]
impl Default for StaticHistoryPolicy {
    fn default() -> Self {
        Self::new()
    }
}

// ======================================================================
// StatePolicy trait implementation
// ======================================================================

impl StatePolicy for StaticHistoryPolicy {
    type State = StaticHistoryState;
    type Event = StaticHistoryEvent;
    type History = StaticHistoryHistory;
    // EventSchema native lowering: `()` = schemaless (dynamic
    // `_event.data` baseline); a `<Machine>Payload` sum is emitted when a
    // transition guard reads a typed `_event.data.<field>` (NL→IR C1 Path A).
    type Payload = ();
    type Hal = sce_rust_runtime::StdHal;

    // W3C SCXML Appendix D internalQueue / externalQueue. Under no_std the
    // depth is the per-document `<scxml sce:capacity>` / deploy value (emitted
    // as the const consumed below); absent a declared capacity the bare form
    // inherits the runtime default `MAX_EVENT_QUEUE_DEPTH` (the single source of
    // the default). Inert under std (`VecDeque`), so this one emission compiles
    // on both runtime profiles. The queue holds events as numbers and only the
    // payloads as this machine's type (docs/adr/0068).
    type EventQueue = sce_rust_runtime::EventQueue<Self::Payload>;

    // W3C SCXML 6.3: the delayed-send scheduler keeps a per-entry `send_id` only
    // so `<cancel sendid>` can find and drop the matching entry; the timer-fire
    // drain never reads it. A document with no `<cancel>` therefore emits the
    // zero-size `ElidedSendId`, shedding the scheduler ring's per-entry
    // `heapless::String<256>` (~256 B x MAX_SCHEDULED_EVENTS) under no_std --
    // dead weight with no cancel reader. A cancelling document keeps the
    // load-bearing `SceString`. Behaviour-preserving under std either way, so
    // this one emission compiles on both runtime profiles. Mirrors the
    // EventQueue per-machine sizing lever above.
    type ScheduledSendId = sce_rust_runtime::ElidedSendId;

    // docs/adr/0064: the document as the runtime's Appendix D procedures read
    // it, which are compiled once for a program: its tables, and its states,
    // histories and events by the numbers the tables know them by. Each of the
    // three lists is in the order of those numbers, so it is the inverse of the
    // enum's discriminant.
    const TABLES: &'static ::sce_rust_runtime::DocumentTables = &STATIC_HISTORY_TABLES;
    const STATES: &'static [Self::State] = &[
        StaticHistoryState::Running,
        StaticHistoryState::Slow,
        StaticHistoryState::Fast,
        StaticHistoryState::Cruise,
        StaticHistoryState::Burst,
        StaticHistoryState::Working,
        StaticHistoryState::Crew,
        StaticHistoryState::Left,
        StaticHistoryState::L1,
        StaticHistoryState::L2,
        StaticHistoryState::Right,
        StaticHistoryState::R1,
        StaticHistoryState::R2,
        StaticHistoryState::Paused,
    ];
    const HISTORIES: &'static [Self::History] = &[
        StaticHistoryHistory::CrewAll,
        StaticHistoryHistory::Deepest,
        StaticHistoryHistory::Last,
    ];
    const EVENTS: &'static [Self::Event] = &[
        StaticHistoryEvent::Boost,
        StaticHistoryEvent::Break,
        StaticHistoryEvent::Faster,
        StaticHistoryEvent::LeftNext,
        StaticHistoryEvent::Pause,
        StaticHistoryEvent::ResumeCrew,
        StaticHistoryEvent::ResumeDeep,
        StaticHistoryEvent::ResumeLast,
        StaticHistoryEvent::RightNext,
        StaticHistoryEvent::Work,
        StaticHistoryEvent::Null,
    ];

    fn state_id(state: Self::State) -> ::sce_rust_runtime::StateId {
        ::sce_rust_runtime::StateId(state as u16)
    }

    fn history_id(history: Self::History) -> ::sce_rust_runtime::HistoryId {
        ::sce_rust_runtime::HistoryId(history as u16)
    }

    fn event_id(event: Self::Event) -> ::sce_rust_runtime::EventId {
        ::sce_rust_runtime::EventId(event as u16)
    }

    // W3C SCXML 3.4: what this document's state tree bounds, read by the
    // generator and written here so every buffer of the runtime's microstep is
    // this document's size and no larger, in both profiles. Every set of states
    // the runtime keeps is a bit vector of this document's 14 state(s); a
    // configuration holds 6 state(s) at most, the capacity of the
    // `Configuration` a host reads; a selection enables 2 transition(s) at most, one from each atomic state
    // of one configuration; a microstep owes 2 history default(s) at most;
    // and Appendix D's entry procedures, the effective targets and the
    // completion check are run over a stack of steps and not by recursion, so a
    // call needs no depth the program has to assume: 18 step(s) at most, three
    // for each level of the tree, one for each `<history>` and three of
    // headroom. The workspace is a local of the call that runs a macrostep; the
    // run store, the configuration and what each of the 3 `<history>`
    // element(s) recorded, one such set each, is the engine's.
    type Workspace =
        ::sce_rust_runtime::Workspace<{ ::sce_rust_runtime::state_scratch(14) }, 2, 18, 2>;
    type RunStore = ::sce_rust_runtime::RunStore<
        { ::sce_rust_runtime::state_words(14) },
        { ::sce_rust_runtime::record_words(14, 3) },
        3,
    >;
    type Configuration = StaticHistoryConfiguration;

    // W3C SCXML feature flags
    const HAS_PARALLEL_STATES: bool = true;
    const NEEDS_SCRIPT_ENGINE: bool = false;
    const NEEDS_DATA_MODEL_INIT: bool = false;
    // The same fact the generate manifest publishes as `needs_event_scheduler`.
    // A `build.rs` consumer never sees that manifest — `compile_scxml` returns
    // `()` — so without this constant a host had no route to the knowledge that
    // its driving loop must call `tick()` rather than `step()`.
    const NEEDS_EVENT_SCHEDULER: bool = false;
    // The generate manifest's `needs_parent`: what a root-start policy reads.
    const NEEDS_PARENT: bool = false;

    // ======================================================================
    // Static metadata methods (W3C SCXML document structure)
    // ======================================================================

    // The document's structure — each state's parent, kind, subtree and
    // initial transition, and so its children, each history's parent and
    // default, document order — is read from `TABLES` by the trait's own
    // methods (docs/adr/0064), so none of it is written here a second time.

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            StaticHistoryEvent::Boost => "boost",
            StaticHistoryEvent::Break => "break",
            StaticHistoryEvent::Faster => "faster",
            StaticHistoryEvent::LeftNext => "left_next",
            StaticHistoryEvent::Pause => "pause",
            StaticHistoryEvent::ResumeCrew => "resume_crew",
            StaticHistoryEvent::ResumeDeep => "resume_deep",
            StaticHistoryEvent::ResumeLast => "resume_last",
            StaticHistoryEvent::RightNext => "right_next",
            StaticHistoryEvent::Work => "work",
            StaticHistoryEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "boost" => Some(StaticHistoryEvent::Boost),
            "break" => Some(StaticHistoryEvent::Break),
            "faster" => Some(StaticHistoryEvent::Faster),
            "left_next" => Some(StaticHistoryEvent::LeftNext),
            "pause" => Some(StaticHistoryEvent::Pause),
            "resume_crew" => Some(StaticHistoryEvent::ResumeCrew),
            "resume_deep" => Some(StaticHistoryEvent::ResumeDeep),
            "resume_last" => Some(StaticHistoryEvent::ResumeLast),
            "right_next" => Some(StaticHistoryEvent::RightNext),
            "work" => Some(StaticHistoryEvent::Work),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StaticHistoryState::Burst => "burst",
            StaticHistoryState::Crew => "crew",
            StaticHistoryState::Cruise => "cruise",
            StaticHistoryState::Fast => "fast",
            StaticHistoryState::L1 => "l1",
            StaticHistoryState::L2 => "l2",
            StaticHistoryState::Left => "left",
            StaticHistoryState::Paused => "paused",
            StaticHistoryState::R1 => "r1",
            StaticHistoryState::R2 => "r2",
            StaticHistoryState::Right => "right",
            StaticHistoryState::Running => "running",
            StaticHistoryState::Slow => "slow",
            StaticHistoryState::Working => "working",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the slice `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "burst" => Some(StaticHistoryState::Burst),
            "crew" => Some(StaticHistoryState::Crew),
            "cruise" => Some(StaticHistoryState::Cruise),
            "fast" => Some(StaticHistoryState::Fast),
            "l1" => Some(StaticHistoryState::L1),
            "l2" => Some(StaticHistoryState::L2),
            "left" => Some(StaticHistoryState::Left),
            "paused" => Some(StaticHistoryState::Paused),
            "r1" => Some(StaticHistoryState::R1),
            "r2" => Some(StaticHistoryState::R2),
            "right" => Some(StaticHistoryState::Right),
            "running" => Some(StaticHistoryState::Running),
            "slow" => Some(StaticHistoryState::Slow),
            "working" => Some(StaticHistoryState::Working),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        StaticHistoryEvent::Null
    }

    // ======================================================================
    // Instance methods - generated executable content
    // ======================================================================

    // W3C SCXML 3.7: Execute <onentry> actions for a state
    #[doc = "SCE-MAP: static_history.scxml:33 :: _machine"]
    // SCE-MAP: static_history.scxml:33 :: _machine
    fn execute_entry_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
        is_default_entry: bool,
    ) {
    }

    // §scxml-3.10.2: a <history>'s default transition content, run after its
    // parent's onentry (and after the parent's own <initial> content) when the
    // history was taken with nothing recorded. The engine asks for it by the
    // entry set's defaultHistoryContent answer; a history that restored what it
    // recorded runs nothing.

    // W3C SCXML 3.8: Execute <onexit> actions for a state
    #[doc = "SCE-MAP: static_history.scxml:33 :: _machine"]
    // SCE-MAP: static_history.scxml:33 :: _machine
    fn execute_exit_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) {
        // §scxml-D-exitStates orders one state's exit as onexit, then
        // cancelInvoke, then configuration.delete(s), so `In(s)` inside s's
        // own handler is true. The engine recorded every history this exit
        // set records before its first exit (W3C SCXML 3.10), and removes
        // `state` from the configuration after this returns.
    }

    // Appendix D selectTransitions, the half only this document can answer:
    // the first of `state`'s own transitions, in document order, that `event`
    // enables, as its row of the tables, which holds its targets and its
    // type. The engine walks the atomic states and their ancestors and keeps
    // the ordered set. `Event::Null` asks for eventless transitions.
    #[doc = "SCE-MAP: static_history.scxml:33 :: _machine"]
    // SCE-MAP: static_history.scxml:33 :: _machine
    fn first_enabled_transition(
        &mut self,
        state: Self::State,
        event: Self::Event,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) -> Option<::sce_rust_runtime::TransitionId> {
        match state {
            StaticHistoryState::Cruise => {
                if event == StaticHistoryEvent::Boost {
                    {
                        // cruise, transition 0
                        return Some(::sce_rust_runtime::TransitionId(2));
                    }
                }
                None
            }
            StaticHistoryState::L1 => {
                if event == StaticHistoryEvent::LeftNext {
                    {
                        // l1, transition 0
                        return Some(::sce_rust_runtime::TransitionId(4));
                    }
                }
                None
            }
            StaticHistoryState::Paused => {
                if event == StaticHistoryEvent::Work {
                    {
                        // paused, transition 0
                        return Some(::sce_rust_runtime::TransitionId(6));
                    }
                }
                if event == StaticHistoryEvent::ResumeLast {
                    {
                        // paused, transition 1
                        return Some(::sce_rust_runtime::TransitionId(7));
                    }
                }
                if event == StaticHistoryEvent::ResumeDeep {
                    {
                        // paused, transition 2
                        return Some(::sce_rust_runtime::TransitionId(8));
                    }
                }
                if event == StaticHistoryEvent::ResumeCrew {
                    {
                        // paused, transition 3
                        return Some(::sce_rust_runtime::TransitionId(9));
                    }
                }
                None
            }
            StaticHistoryState::R1 => {
                if event == StaticHistoryEvent::RightNext {
                    {
                        // r1, transition 0
                        return Some(::sce_rust_runtime::TransitionId(5));
                    }
                }
                None
            }
            StaticHistoryState::Running => {
                if event == StaticHistoryEvent::Pause {
                    {
                        // running, transition 0
                        return Some(::sce_rust_runtime::TransitionId(0));
                    }
                }
                None
            }
            StaticHistoryState::Slow => {
                if event == StaticHistoryEvent::Faster {
                    {
                        // slow, transition 0
                        return Some(::sce_rust_runtime::TransitionId(1));
                    }
                }
                None
            }
            StaticHistoryState::Working => {
                if event == StaticHistoryEvent::Break {
                    {
                        // working, transition 0
                        return Some(::sce_rust_runtime::TransitionId(3));
                    }
                }
                None
            }
            _ => None,
        }
    }

    // W3C SCXML 3.13: a transition's executable content, run by the engine
    // between the microstep's exits and its entries. `transition` is a
    // written transition's row, one whose row says it has content.
    #[doc = "SCE-MAP: static_history.scxml:33 :: _machine"]
    // SCE-MAP: static_history.scxml:33 :: _machine
    fn execute_transition_content(
        &mut self,
        transition: ::sce_rust_runtime::TransitionId,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) {
        match transition.0 {
            // paused, transition 1
            7 => {
                // SCE-MAP: static_history.scxml:78 :: paused :: _transition_1
                // W3C SCXML 3.13: Transition 1 actions
                // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                'action_block: {
                    // W3C SCXML 5.3: <assign location="resumed">
                    let sce_failed =
                        match (|| -> Result<(), sce_forge_runtime::algorithm::AlgorithmError> {
                            self.resumed =
                                sce_forge_runtime::algorithm::add::<u8>(self.resumed, 1)?;
                            Ok(())
                        })() {
                            Ok(()) => false,
                            Err(_) => true,
                        };
                    if sce_failed {
                        break 'action_block; // W3C SCXML 4.9: the error ends the block
                    }
                }
            }
            _ => {}
        }
    }

    // W3C SCXML 6.2 + 6.4: a delayed `<send target="#_parent">` whose wait is
    // over, with the payload an immediate one carries. It waited in this
    // machine's own queue, so `<cancel>` reached it and a child that ended
    // first dropped it — the engine dispatches nothing once final.
    fn deliver_to_parent(&mut self, event_name: &str, event_data: &str) -> bool {
        if let Some(ref parent_queue) = self.parent_external_queue {
            if let Ok(mut q) = parent_queue.lock() {
                q.push((event_name.to_string(), event_data.to_string()));
                return true;
            }
        }
        false
    }

    // W3C SCXML C.1: whether a session invoked this one — the queue the
    // invoking parent installs is the link to it.
    fn has_parent_session(&self) -> bool {
        self.parent_external_queue.is_some()
    }

    // docs/adr/0045: this session's own id, as a saved state holds it.
    fn own_session_id(&self) -> &str {
        self.session_id.as_deref().unwrap_or("")
    }

    // docs/adr/0045: a restored session carries on under its saved id.
    fn bind_session_id(&mut self, session_id: &str) {
        self.session_id = Some(session_id.to_string());
    }
}
